import { Component, OnInit, Input, Output, EventEmitter } from '@angular/core';
import { CreateSecurity, Issuer, SecuritiesService, Security, TypeSecurity } from './securities.service';
import { LoginService } from '../auth/login/login.service';

@Component({
  selector: 'app-securities',
  templateUrl: './securities.component.html',
  styleUrls: ['./securities.component.css']
})
export class SecuritiesComponent implements OnInit {
  securities: Security[] = [];
  loading: boolean = true;
  errorMessage: string | null = null;
  showDeleteModal = false;
  securityToDelete: Security | null = null;
  showEditModal = false;
  securityToEdit: Security | undefined = undefined;

  isAdmin = false;

  constructor(private securitiesService: SecuritiesService, public loginService: LoginService) { }

  ngOnInit(): void {
    this.loadSecurities();
    this.loginService.getUserRoles().subscribe(roles => {
      this.isAdmin = roles.includes('Администратор');
    })
  }


  loadSecurities(): void {
    this.securitiesService.getAll().subscribe({
      next: (securities) => {
        this.securities = securities;
        this.loading = false;
      },
      error: (error) => {
        this.errorMessage = 'Could not load securities.';
        this.loading = false;
      }
    });
  }

  openDeleteModal(security: Security): void {
    this.securityToDelete = security;
    this.showDeleteModal = true;
  }

  closeDeleteModal(): void {
    this.showDeleteModal = false;
    this.securityToDelete = null;
  }

  confirmDelete(): void {
    if (!this.securityToDelete) return;

    this.securitiesService.deleteSecurity(this.securityToDelete.id).subscribe({
      next: () => {
        this.securities = this.securities.filter(s => s.id !== this.securityToDelete?.id);
        this.closeDeleteModal();
      },
      error: (err) => {
        console.error('Failed to delete security:', err);
        this.errorMessage = 'Failed to delete security.';
        this.closeDeleteModal();
      }
    });
  }

  openAddModal() {
    this.securityToEdit = undefined;
    this.showEditModal = true;
  }

  openEditModal(security: Security) {
    this.securityToEdit = security;
    this.showEditModal = true;
  }

  onModalClose(updatedSecurity: Security | null) {
    this.showEditModal = false;
    if (!updatedSecurity) return;

    if (this.securityToEdit) {
      const index = this.securities.findIndex(s => s.id === updatedSecurity.id);
      if (index > -1) this.securities[index] = updatedSecurity;
    } else {
      this.securities.push(updatedSecurity);
    }
  }
}
<div class="securities-section">
  <h2 class="text-center mt-4">Securities</h2>

  <div class="text-md-end mb-3" *ngIf="isAdmin">
    <button class="btn btn-success btn-sm" (click)="openAddModal()">Add Security</button>
  </div>

  <div *ngIf="securities.length > 0; else noData">
    <table class="table table-striped table-hover mt-3">
      <thead class="table-primary">
        <tr>
          <th>Code</th>
          <th>ISIN</th>
          <th>Type</th>
          <th>Issuer</th>
          <th>Total Shares</th>
          <th *ngIf="isAdmin">Actions</th>
        </tr>
      </thead>
      <tbody>
        <tr *ngFor="let sec of securities">
          <td>{{ sec.code }}</td>
          <td>{{ sec.isin }}</td>
          <td>{{ sec.typeSecurityName }}</td>
          <td>{{ sec.issuerName }}</td>
          <td>{{ sec.totalNumShares | number }}</td>
          <td *ngIf="isAdmin">
            <button class="btn btn-warning btn-sm me-1" (click)="openEditModal(sec)">Edit</button>
            <button class="btn btn-danger btn-sm" (click)="openDeleteModal(sec)">Delete</button>
          </td>
        </tr>
      </tbody>
    </table>
  </div>

  <ng-template #noData>
    <p class="text-center text-muted mt-3">No securities available.</p>
  </ng-template>
</div>

<app-add-security
  *ngIf="showEditModal"
  [securityToEdit]="securityToEdit"
  (close)="onModalClose($event)">
</app-add-security>

<div *ngIf="showDeleteModal" class="modal-overlay">
  <div class="modal-content animate-in">
    <h3>Confirm Delete</h3>
    <p>
      Are you sure you want to delete security with ISIN
      <strong>{{ securityToDelete?.isin }}</strong>?
    </p>
    <div class="modal-actions">
      <button class="btn btn-danger" (click)="confirmDelete()">Delete</button>
      <button class="btn btn-secondary" (click)="closeDeleteModal()">Cancel</button>
    </div>
  </div>
</div>
